questions.solution:
def graph_speedup(L, ell, build, n, w):
    """Speedup of n kernels of length w replayed from a graph built once, over n direct launches."""
    return n * (L + w) / (build + n * (ell + w))


def crossover_w(L, ell, build, n, target):
    """The kernel length w at which graph_speedup falls to target, or 0.0 if it never reaches it."""
    base = ell + build / n
    w = (L - target * base) / (target - 1)
    return max(w, 0.0)
